import {goalKey,dayKey,addDays,reviewSchedule,practiceActivity} from './workshop-review.mjs';
const p=(es,en)=>({es,en});
export function mountReviews(api){
 const root=document.createElement('section');root.id='reviewCalendar';root.className='challenge-panel';api.before.before(root);
 let selected=dayKey(),month=selected.slice(0,7),goal=2,error=false,showAll=false;
 try{const n=Number(localStorage.getItem(goalKey));if(Number.isInteger(n)&&n>=1&&n<=10)goal=n;}catch{}
 const el=(tag,text,host)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;},t=x=>x[api.lang()];
 function render(){const now=new Date(),today=dayKey(now),rows=api.results(),schedule=reviewSchedule(rows,now),activity=practiceActivity(rows,now);root.replaceChildren();
 el('h2',t(p('Tu calendario de repasos','Your review calendar')),root);
 el('p',t(p('Repasos de mediciones y diagnósticos: 1, 3, 7, 14 y 30 días tras días de práctica correctos con hasta una pista. Un error o dos pistas devuelve el intervalo a 1 día. Repetir el mismo día no alarga el intervalo.','Measurement and diagnosis reviews: 1, 3, 7, 14 and 30 days after successful practice days using at most one hint. An error or two hints resets the interval to 1 day. Repeating on the same day does not lengthen it.')),root);
 const metrics=el('div','',root);metrics.className='review-metrics';el('strong',t(p('Hoy: ','Today: '))+activity.today+'/'+goal,metrics);el('strong',t(p('Racha: ','Streak: '))+activity.streak+' '+t(p('días','days')),metrics);
 const label=el('label',t(p('Meta diaria de retos verificados ','Daily verified-challenge goal ')),root);const input=el('input','',label);input.id='dailyReviewGoal';input.type='number';input.min=1;input.max=10;input.value=goal;input.onchange=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<1||n>10){input.value=goal;return;}goal=n;try{localStorage.setItem(goalKey,String(goal));error=false;}catch{error=true;}render();};
 const progress=el('progress','',root);progress.max=goal;progress.value=Math.min(goal,activity.today);progress.setAttribute('aria-label',t(p('Progreso de la meta diaria','Daily goal progress')));
 el('p',t(activity.today>=goal?p('¡Meta del día completada!','Daily goal completed!'):p('Completa y verifica un reto para avanzar. Abrir un banco no cuenta.','Complete and verify a challenge to advance. Opening a bench does not count.')),root);
 el('p',t(p('La racha requiere al menos un reto verificado por día, aunque tu meta sea mayor. Usa las fechas locales de tu navegador. Datos locales, basados en los últimos 200 resultados guardados; el historial anterior puede quedar fuera del cálculo.','A streak requires at least one verified challenge per day, even if your goal is higher. Dates use your browser’s local time. Local data is based on the last 200 saved results; older history may fall outside the calculation.')),root);
 if(error)el('p',t(p('No se pudo guardar la meta; se mantiene solo en esta visita.','The goal could not be saved; it is kept only for this visit.')),root).setAttribute('role','status');
 const nav=el('div','',root);nav.className='controls';for(const [delta,title]of [[-1,p('Mes anterior','Previous month')],[1,p('Mes siguiente','Next month')]]){const b=el('button',t(title),nav);b.onclick=()=>{const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+delta);month=dayKey(d).slice(0,7);selected=month+'-01';render();};}const back=el('button',t(p('Hoy','Today')),nav);back.onclick=()=>{selected=today;month=today.slice(0,7);render();};
 el('h3',new Date(month+'-01T12:00:00').toLocaleDateString(api.lang(),{month:'long',year:'numeric'}),root);
 const grid=el('div','',root);grid.className='review-calendar-grid';const first=new Date(month+'-01T12:00:00');for(let i=0;i<7;i++)el('span',new Date(2024,0,1+i).toLocaleDateString(api.lang(),{weekday:'short'}),grid);for(let i=0;i<(first.getDay()+6)%7;i++)el('span','',grid);
 for(let date=month+'-01';date.startsWith(month);date=addDays(date,1)){const due=schedule.filter(s=>s.due===date||(date===today&&s.due<today)).length,count=activity.counts[date]??0;const b=el('button',String(Number(date.slice(-2))),grid);b.dataset.reviewDay=date;b.setAttribute('aria-pressed',String(selected===date));if(date===today)b.setAttribute('aria-current','date');el('small',(date>=today?due+' '+t(p('pend.','due'))+' · ':'')+count+' ✓',b);b.setAttribute('aria-label',date+' · '+due+' '+t(p('habilidades pendientes','skills due'))+' · '+count+' '+t(p('retos terminados','completed challenges')));b.onclick=()=>{selected=date;render();};}
 el('h3',selected+' · '+t(p('Plan del día','Day plan')),root);
 el('p',t(p('Los números pendientes cuentan habilidades; un reto puede repasar varias. Las fechas futuras son una previsión que cambia al practicar.','Due counts represent skills; one challenge can review several. Future dates are a forecast that updates with practice.')),root);
 const requested=new URLSearchParams(location.search).get('review');const chosen=schedule.find(s=>s.key===requested);let entries=selected<today?[]:schedule.filter(s=>s.due===selected||(selected===today&&s.due<today));if(chosen&&selected===today)entries=[chosen,...entries.filter(e=>e.key!==chosen.key)];
 if(selected<today)el('p',(activity.counts[selected]??0)+' '+t(p('retos terminados. No se reconstruye el plan histórico.','completed challenges. Historical schedules are not reconstructed.')),root);
 else if(!entries.length)el('p',t(p('No hay repasos programados para esta fecha. Puedes practicar con Nuevo reto adaptativo.','No reviews scheduled for this date. You can practise using New adaptive challenge.')),root);
 const list=el('div','',root);list.className='review-list';for(const entry of entries.slice(0,showAll?entries.length:6)){const card=el('article','',list);el('h4',api.name(entry),card);if(entry.due>today)el('p',t(p('Repaso anticipado disponible; todavía no está vencido.','Early review available; this skill is not due yet.')),card);el('p',t(entry.seen?p('Último repaso: ','Last reviewed: '):p('Primera práctica','First practice'))+(entry.last??'')+' · '+t(p('Vence: ','Due: '))+entry.due+(entry.seen?' · '+entry.errors+'/'+entry.seen+' '+t(p('días con errores o ayuda extra','days with errors or extra help')):' · '+t(p('Aún sin evaluar','Not assessed yet'))),card);const button=el('button',t(p('Practicar en 3D','Practise in 3D')),card);button.dataset.review=entry.key;button.disabled=api.busy();button.onclick=()=>{if(entry.kind===api.kind){api.start(entry);document.querySelector('#benches').scrollIntoView({behavior:'auto',block:'start'});}else location.href='workshop.html?case='+entry.kind+'&lang='+api.lang()+'&review='+encodeURIComponent(entry.key)+'#reviewCalendar';};}
 if(entries.length>6){const more=el('button',t(showAll?p('Mostrar menos','Show fewer'):p('Ver todos los repasos','Show all reviews'))+' ('+entries.length+')',root);more.onclick=()=>{showAll=!showAll;render();};}
 if(api.busy())el('p',t(p('Termina el reto activo o reinícialo antes de abrir un repaso.','Finish or reset the active challenge before opening a review.')),root);
 }
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});return {render};
}
